#define CALIBRATION_UH 90  // Default upper humidity value
#define CALIBRATION_LL 40  // Default lower temperature value
#define CALIBRATION_UL 80  // Default upper temperature value

// Create a DHT22 object
DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(9600);
  dht.begin();
