void loop() {
  // Take readings and calculate the actual humidity and temperature
  float h = dht.readHumidity();
  float t = dht.readTemperature();

  // Check if the readings are valid
  if (isnan(h) || isnan(t)) {
    Serial.println("Failed to read from DHT22!");
    delay(2000);
    return;
  }

  // Calculate the actual reading ratio based on the calibration values
  float h_ratio = (h - CALIBRATION_LL) / (CALIBRATION_UH - CALIBRATION_LL);
  float t_ratio = (t - CALIBRATION_LL) / (CALIBRATION_UL - CALIBRATION_LL);

  // Get the calibrated readings
  float calibrated_h = h_ratio * (100 - CALIBRATION_LL) + CALIBRATION_LL;
  float calibrated_t = t_ratio * (CALIBRATION_UL - CALIBRATION_LL) + CALIBRATION_LL;

  // Print the calibrated readings
  Serial.print("Calibrated Humidity: ");
  Serial.print(calibrated_h);
  Serial.println(" %");
  Serial.print("Calibrated Temperature: ");
  Serial.print(calibrated_t);
  Serial.println(" *C");

  delay(2000);
}
```
