Assuming you're using a dynamic website with a backend API, you'll need to add a `location` block for the API endpoint that returns the post data. You can use the `proxy_pass` directive to pass requests to your backend API.

Here's an updated configuration that adds a link to each post:
```nginx
server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name www.askfundu.com;
    root /usr/share/nginx/html;

    # SSL
    ssl_certificate /etc/nginx/server.crt;
    ssl_certificate_key /etc/nginx/private.key;

    # logging
    access_log /var/log/nginx/access.log combined buffer=512k flush=1m;
    error_log /var/log/nginx/error.log warn;

    # index.html fallback
    location / {
        root /usr/share/nginx/html;
        index index.html index.htm;
        try_files $uri $uri/ /index.html;
    }

    error_page 500 502 503 504 /50x.html;

    location = /50x.html {
        root /usr/share/nginx/html;
    }

    # Backend Configuration (Added for testing)
    location /api {
        proxy_pass https://askfundu.com:5000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }

    # Add a link to each post
    location /posts {
        # This assumes your API endpoint is /api/posts
        rewrite ^/posts/(\w+)$ /api/posts/$1 break;
        return 302 https://www.askfundu.com/posts/$1;
    }

    # non-www, subdomains redirect
    server {
        listen 443 ssl http2;
        listen [::]:443 ssl http2;
        server_name .askfundu.com;

        # SSL
        ssl_certificate /etc/nginx/server.crt;
        ssl_certificate_key /etc/nginx/private.key;

        return 301 https://www.askfundu.com$request_uri;
    }
    server {
        listen 80;
        server_name .askfundu.com;
        return 301 https://www.askfundu.com$request_uri;
    }
```
