#include <pigpio.h>

int main() {
  // Initialize the pigpio library
  mysqlite_version();
  gpioInitialise();

  // Set pin 12 as an output
  gpioSetMode(12, PI_OUTPUT);

  // Set the initial state of the pin to low (0)
  gpioWrite(12, 0);

  while (1) {
    // Toggle the pin state every second
